 await scenario('cross-character-and-owner-ABA-hide-late-directory-and-explanation',async()=>{const old={...idleState(),phase:'selected' as const,directory:{char:'革',status:'available' as const,items:[item()]},explanation:{char:'革',selectionKey:item().selectionKey,meaning:'OWNER-A-EXPLANATION',manualReason:'人工',limits:[]}};const a=await setup({state:old});check(!!query('[data-manual-meaning-explanation]'),'Initial owner explanation missing');await a.render({value:'姿',ownerKey:'owner-B'});check(!query('[data-manual-meaning-option]')&&!query('[data-manual-meaning-explanation]'),'Cross-character reply displayed');await a.render({value:'革',ownerKey:'owner-A-after-B'});check(!container.textContent?.includes('OWNER-A-EXPLANATION'),'A-B-A revived retired owner result');check(actions('select').length===0,'Stale key remains selectable');equal(events,[],'Owner changes emitted query/selection automatically');});
 await scenario('error-unavailable-and-escaped-source-remain-controlled',async()=>{const a=await setup({state:{...idleState(),phase:'error',error:'目录资源暂不可读；没有回退。'}});check(container.querySelector('[role="alert"]')?.textContent?.includes('目录资源暂不可读'),'Error missing');equal(events,[],'Error retried query');await a.render({state:{...idleState(),phase:'unavailable',error:'入口尚未接入'}});check(actions('query')[0].disabled,'Unavailable service still dispatchable');const hostile='<img src=x onerror="bad()"><script>bad()</script>';await a.render({state:{...idleState(),phase:'ready',directory:{char:'革',status:'available',items:[{...item(),originalMeaning:hostile,sourceCitation:{...item().sourceCitation,dictionaryName:hostile}}]}}});check(!query('script')&&!query('img'),'Controlled original/source text became markup');check(container.textContent?.includes(hostile),'Escaped literal original text disappeared');check(!container.innerHTML.includes(item().selectionKey),'Opaque selection key visible');});
